function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000);}
function download(name,rows){if(!rows.length)return toast('확보된 데이터가 없습니다.');const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))],q=v=>{let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(q).join(',')).join('\r\n');const a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('실측 데이터 CSV를 내보냈습니다.');}
function downloadJSON(){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));a.href=u;a.download='social-pulse-real-'+(D.latest_run?.date||D.as_of)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function goal(){ $('#goalLabel').textContent=fmt(target);$('#target').textContent=fmt(target);$('#weekViews').textContent='집계 대기';$('#weekViews').style.fontSize='28px';$('#percent').textContent='동일 기간 자료 부족';$('#progress').style.width='0%';$('.track').setAttribute('aria-label','달성률 미산출: 동일 기간 자료 부족');$('#remaining').textContent='두 채널의 10.19~10.25 동일 기간 데이터가 확보되면 계산합니다.';$('#recommended').textContent='추천 보류';$('#reason').textContent='완료된 4주치 실제 데이터가 아직 부족합니다. 임의 목표를 추천하지 않습니다.';$('#usegoal').disabled=true;$('#usegoal').textContent='4주 실측 데이터 확보 후 제공';$('.goalmain > p').textContent='목표만 저장할 수 있습니다. 기간이 다른 조회수는 합산하지 않습니다.';}
function ytRows(){const start=days?addDays(D.youtube.end,1-days):D.youtube.start;return D.youtube.daily.filter(r=>r['날짜']>=start&&r['날짜']<=D.youtube.end).sort((a,b)=>a['날짜'].localeCompare(b['날짜']));}
function metric(k,label,note){return '<div class="metric"><span>'+esc(label)+'</span><strong>'+esc(typeof k==='string'?k:fmt(k))+'</strong><small>'+esc(note||'')+'</small></div>';}
function renderChannels(){const ip=D.instagram.periods.find(p=>p.days===(days===0?90:days)),yr=ytRows(),yt=D.youtube.total;const igPeriod=ip?'최근 '+ip.days+'일 · 절대 날짜 경계 미표시':'최근 1일 자료 미확보';const yrange=yr.length?yr[0]['날짜']+' ~ '+yr[yr.length-1]['날짜']:'자료 없음';$('#range').textContent='Instagram: '+igPeriod+' | YouTube: '+yrange;let ic='<article class="channel"><div class="channeltop"><div class="channelicon">◎</div><div><b>Instagram</b><small><a href="'+esc(D.instagram.url)+'" target="_blank" rel="noopener">@tepo_001</a> · 실제 계정</small></div><button data-export="Instagram">↓ CSV</button></div><p class="source-note">'+esc(igPeriod)+'</p><div class="metrics">'+metric(26,'현재 팔로워','2026.10.23 수집')+metric(13,'현재 게시물','계정 전체 · 선택 기간 발행수 아님')+metric(ip?.views??null,'기간 조회수',ip?'계정 인사이트 표시값':'미확보 · 0이 아닙니다')+metric(ip?.interactions??null,'기간 반응','구매·링크 클릭 전환 아님')+metric(ip?.external_link_taps??null,'외부 링크 누름','프로필 외부 링크 · 중첩 기간 합산 금지')+'</div><p class="source-note">'+(ip?'조회한 사람 '+fmt(ip.people_viewed)+' · 참여 계정 '+fmt(ip.engaged_accounts)+' · 프로필 방문 '+fmt(ip.profile_visits):'일별 조회수와 계정 통합 댓글·저장·공유는 미확보')+'</p></article>';
let yc='<article class="channel youtube"><div class="channeltop"><div class="channelicon">▶</div><div><b>YouTube</b><small><a href="'+esc(D.youtube.url)+'" target="_blank" rel="noopener">테포</a> · 실제 채널</small></div><button data-export="YouTube">↓ CSV</button></div><p class="source-note">'+esc(yrange)+' · 분석 반영일 10.21'+(days===30?' · 확보된 17일만 표시':'')+'</p><div class="metrics">'+metric(6,'현재 구독자','2026.10.23 수집')+metric(7,'현재 공개 영상','Shorts 6개 · 일반 동영상 1개')+metric(sum(yr,'조회수'),'기간 조회수','분석 보고서 · 최신 누적/실시간과 별도')+metric(sum(yr,'좋아요'),'기간 좋아요','저장·리포스트 미확보')+metric(sum(yr,'추가된 댓글 수'),'기간 추가 댓글','현재 남아 있는 댓글 수와 정의 다름')+'</div><p class="source-note">시청시간 '+sum(yr,'시청 시간(단위: 시간)').toFixed(4)+'시간 · 공유 '+fmt(sum(yr,'공유'))+' · 유효 조회수 '+fmt(sum(yr,'유효 조회수'))+'</p></article>';
$('#channels').innerHTML=ic+yc;document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{if(b.dataset.export==='Instagram')download('instagram-summary-2026-10-23',[{account:'tepo_001',observed_at:D.as_of,followers_current:26,posts_current:13,period:igPeriod,...(ip||{})}]);else download('youtube-daily-real-2026-10-23',yr);});}
function contentRows(){const ig=D.instagram.contents.map(c=>({channel:'Instagram',title:'Instagram '+({reel:'릴스',carousel:'슬라이드',image:'게시물'}[c.type]||c.type)+' · '+c.date,type:{reel:'릴스',carousel:'슬라이드',image:'게시물'}[c.type]||c.type,date:c.date,url:c.url,views:val(c.views),views_display:shown(c.views),likes:val(c.likes),comments:val(c.comments),saves:val(c.saves),shares:val(c.shares),views_precision:c.views?.precision,platform_interactions:val(c.interactions),note:'개별 상세 집계기간 미표시; 미표시 리포스트는 null'}));const yt=D.youtube.contents.map(c=>({...c,channel:'YouTube',views_display:fmt(c.views),likes:null,saves:null,shares:null,note:'현재 콘텐츠 목록 누적값; 좋아요·공유의 기간 보고서는 아래 상세 참고'}));return [...ig,...yt].filter(c=>channel==='all'||c.channel===channel).sort((a,b)=>{const ranking=c=>sort==='views'&&c.views_precision==='abbreviated'?Number.parseFloat(c.views_display)*(c.views_display.includes('만')?10000:c.views_display.includes('천')?1000:1):c[sort];const av=ranking(a),bv=ranking(b);if(av==null&&bv!=null)return 1;if(bv==null&&av!=null)return -1;return (bv??-1)-(av??-1)||b.date.localeCompare(a.date);});}
function renderContents(){const rows=contentRows();$('#contentCount').textContent=rows.length;$('#rows').innerHTML=rows.map(c=>'<tr><td><span class="thumb actual-thumb" aria-hidden="true">'+(c.channel==='Instagram'?'IG':'YT')+'<span class="thumb-type">'+esc(c.type)+'</span></span><div><a href="'+esc(c.url)+'" target="_blank" rel="noopener">'+esc(c.title)+'</a><small>'+esc(c.date)+' · '+esc(c.type)+(c.views_precision==='abbreviated'?' · 조회수 축약 표시':'')+(c.restrictions?' · 제한사항 확인 필요':'')+'</small></div></td><td><span class="channelbadge '+(c.channel==='YouTube'?'yt':'')+'">'+c.channel+'</span></td><td><b>'+esc(c.views_display)+'</b></td><td>'+fmt(c.likes)+'</td><td>'+fmt(c.comments)+'</td><td>'+fmt(c.saves)+'</td><td>'+fmt(c.shares)+'</td></tr>').join('');}
function chart(){const rs=ytRows(),n=rs.length,max=Math.max(1,...rs.map(r=>r['조회수']||0)),top=Math.ceil(max/100)*100;let svg='<svg viewBox="0 0 950 175" role="img" aria-label="YouTube 확보된 날짜별 조회수. Instagram 일별 자료는 미확보">';for(let i=0;i<=3;i++){const yy=10+i*130/3;svg+='<line x1="45" x2="940" y1="'+yy+'" y2="'+yy+'" stroke="#edf0e9"/><text x="0" y="'+(yy+4)+'">'+Math.round(top*(1-i/3))+'</text>';}const xp=i=>45+(n===1?450:i*890/(n-1));svg+='<polyline points="'+rs.map((r,i)=>xp(i)+','+(140-(r['조회수']||0)/top*130)).join(' ')+'" fill="none" stroke="#448267" stroke-width="2.5"/>';rs.forEach((r,i)=>{svg+='<circle cx="'+xp(i)+'" cy="'+(140-(r['조회수']||0)/top*130)+'" r="3" fill="#448267"><title>'+esc(r['날짜'])+': '+fmt(r['조회수'])+'</title></circle>';});[...new Set([0,Math.floor((n-1)/2),n-1])].filter(i=>i>=0&&rs[i]).forEach(i=>svg+='<text x="'+xp(i)+'" y="168" text-anchor="middle">'+rs[i]['날짜'].slice(5).replace('-','.')+'</text>');$('#chart').innerHTML=svg+'</svg><p class="source-note">YouTube만 표시 · Instagram 일별 자료 미확보 · 10.22~10.23 미반영분을 0으로 채우지 않았습니다.</p>';}
function supplementary(){const r=D.youtube.total;const html='<section class="chartcard real-details"><h2>실제 데이터 상세 및 집계 기준</h2><p>수집일 2026.10.23 · 수동 스냅샷 · 계정 화면의 시점 차이와 처리 지연이 있을 수 있습니다.</p><details open><summary>집계 주의사항</summary><ul><li>Instagram 계정 최근 90일 조회수 2,473과 최신 릴스 3.2만은 불일치합니다. 원본 표시값을 그대로 보존하며 합산하지 않습니다.</li><li>릴스 3.2만 조회수와 2.6만 조회한 사람은 축약값입니다. 정확한 정수로 치환하지 않았습니다. 이 릴스의 반응 4,562는 좋아요·댓글·저장·공유 합 4,475와 다릅니다. 차이를 리포스트로 추정하지 않습니다.</li><li>콘텐츠 표는 수집 시점 누적값으로, 위 기간 버튼을 바꾸어도 바뀌지 않습니다. Instagram 제목은 원문 캡션을 확보하지 않아 유형·게시일로 표시합니다.</li><li>YouTube 분석 합계 1,294와 콘텐츠별 보고서 6행 합 1,292는 2회 차이가 있습니다. 배분하지 않았습니다. 최신 영상 ‘춤’은 분석 반영일 이후 게시되어 현재 누적 목록에만 있습니다.</li><li>—는 미확보이며 0이 아닙니다. 팔로워·게시물은 현재값으로, 과거 증감률을 추정하지 않습니다.</li><li>축약 조회수는 표기값을 정렬에만 사용합니다. 정확한 수치로 저장하거나 합산하지 않습니다. 계정기간합과 콘텐츠 누적, 확정 분석과 실시간, 서로 다른 날짜와 시간대를 혼합하지 않습니다.</li></ul></details><details><summary>YouTube 전체 분석 · 2026.10.05~10.21</summary><p>조회수 '+fmt(r['조회수'])+' · 시청시간 '+r['시청 시간(단위: 시간)']+'시간 · 유효 조회수 '+fmt(r['유효 조회수'])+' · 순 시청자 '+fmt(r['순 시청자수'])+' · 좋아요 '+fmt(r['좋아요'])+' · 공유 '+fmt(r['공유'])+' · 추가 댓글 '+fmt(r['추가된 댓글 수'])+' · 구독자 순증 '+fmt(r['구독자'])+'</p><p>썸네일 노출 '+fmt(r['썸네일 노출수'])+' · CTR '+r['썸네일 클릭률 (%)']+'% · 평균 시청 '+esc(r['평균 시청 지속 시간'])+' · 평균 조회율 '+r['평균 조회율 (%)']+'%</p><p>수집 당시 지난 48시간 실시간 조회수 '+fmt(D.youtube.realtime.views_last_48h)+'는 위 확정 분석과 별도입니다.</p><button id="ytReportCSV">콘텐츠별 분석 CSV</button></details><details><summary>추가 시청자·콘텐츠 인사이트 · 9.24~10.21</summary><p>Shorts 계속 시청 36.5% · 이탈 63.5% · 유효 조회수 474. 신규 시청자 98.0% · 일반 2.0% · 고정 &lt;0.1%.</p><p>시청시간 기기 비중: 휴대전화 41.7% · 컴퓨터 33.7% · TV 18.4% · 태블릿 6.3%. 대한민국 조회수 비중 10.4%. 연령·성별은 자료 부족.</p></details><details><summary>웹사이트 이후 행동 · GA4 9.25~10.22</summary><p>사용자 '+fmt(D.ga4.totals.total_users)+' · 세션 '+fmt(D.ga4.totals.sessions)+' · 조회수 '+fmt(D.ga4.totals.views)+' · 등대 클릭 33회/4명 · 노출 18회/4명.</p><p>'+esc(D.ga4.note)+' 채널별 세션 행합 40과 총계 35는 불일치합니다. SNS 전환으로 표시하지 않습니다. 클릭은 반복 가능하고 노출은 조건부 측정이므로 33/18을 일반 CTR로 해석하지 않습니다.</p></details></section>';
$('#dashboard footer').insertAdjacentHTML('beforebegin',html);$('#ytReportCSV').onclick=()=>download('youtube-content-report-2026-10-05_to_21',D.youtube.content_report);}
